<GlitchTitle>Anexo B — Tablas y Registros Documentales</GlitchTitle>

Todas las tablas numeradas del trabajo (TABLA 1 – TABLA 27) y la base de datos 
maestra con los registros técnicos completos del incidente del 28 de abril.

export const AnexoB = () => {
  const [tab, setTab] = useState(0);
  return (
    <>
      <TabSelector active={tab} onSelect={setTab} labels={['Tablas numeradas', 'Base de datos maestra']} />
      {tab === 0 && <ForensicGallery />}
      {tab === 1 && <TablaMaestra28A />}
    </>
  );
};
